import flask
from flask import request, jsonify, g
import sqlite3
import os
import hashlib
import time

app = flask.Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        details TEXT
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    db = get_db()
    # Field is validated above, so safe to interpolate.
    # Value is user-controlled but we use LIKE for partial matching.
    query = f"SELECT id, username, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Query failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, role, api_key) VALUES (?, ?, ?, ?)',
            (data['username'], password_hash, 'user', api_key)
        )
        db.commit()
        return jsonify({'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Admin endpoint - exports all user data including API keys."""
    auth = request.headers.get('X-Admin-Key')
    if auth != os.environ.get('ADMIN_SECRET'):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    users = db.execute('SELECT * FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
